flow.set('rr_cancel', false);
const d=new Date().getDay();
msg.mopDay=(d===1||d===5);
return msg;

let n=(flow.get('rr_daily_retry')||0)+1; flow.set('rr_daily_retry',n);
if(n<=8){ node.status({fill:'yellow',shape:'ring',text:'retry '+n+'/8'}); return [msg,null]; }
return [null,msg];

const d=new Date().getDay();
if (d!==1 && d!==5) return [null,msg,null];
if (flow.get('rr_mop_skip')) {
    return [null, msg, {notify:{title:'Vacuum: mop pass skipped',
        message:'Today is a mop day but the dock had a problem at start (see earlier alert). Vacuum pass done; mop skipped.',
        tag:'rr_mop_skipped', urgent:false}}];
}
return [msg,null,null];

msg.url='https://tasks.kmkdp.com/api/v1/projects/6/tasks?per_page=50';
msg.method='GET';
msg.headers={};
return msg;

// Vikunja repeat_mode=2: completing a chore rolls due_date and bumps done_at.
// A done_at change since the last poll = the chore was just done in Vikunja.
const tasks = msg.payload;
if (!Array.isArray(tasks)) return null;
const MAP = {42:0, 43:1, 44:2, 47:3};  // brush, bag, sensors, filter
const outs = [null, null, null, null];
for (const t of tasks) {
    const idx = MAP[t.id];
    if (idx === undefined) continue;
    const key = 'vik_done_' + t.id;
    const last = flow.get(key);
    const cur = t.done_at || '';
    if (last === undefined) { flow.set(key, cur); continue; }
    if (cur !== last) {
        flow.set(key, cur);
        if (cur && !cur.startsWith('0001-')) outs[idx] = {payload:{task:t.id, title:t.title}};
    }
}
return outs.every(o => o === null) ? null : outs;

// throttle: a flapping shortage sensor must not spam completions
const last = flow.get('vik_fill_last') || 0;
if (Date.now() - last < 6*3600*1000) return null;
flow.set('vik_fill_last', Date.now());
msg.url='https://tasks.kmkdp.com/api/v1/tasks/46';
msg.method='GET';
msg.headers={};
return msg;

// Vikunja no-ops on a bare {done:true} — POST the FULL task object back.
const t = msg.payload;
if (!t || !t.id || t.done) return null;
t.done = true;
msg.url='https://tasks.kmkdp.com/api/v1/tasks/46';
msg.method='POST';
msg.headers={'Content-Type':'application/json'};
msg.payload = t;
return msg;

const m = (msg.topic || '').replace('input_button.rr_clean_', '');
if (!m || m === msg.topic) return null;
msg.payload = {stamp: 'input_datetime.rr_last_clean_' + m,
               ts: Math.floor(Date.now()/1000)};
return msg;

const now = new Date();
function nextSlot(dayFilter) {
    for (let d = 0; d < 9; d++) {
        const c = new Date(now.getFullYear(), now.getMonth(), now.getDate() + d);
        const dow = c.getDay();
        if (!dayFilter(dow)) continue;
        const wkend = (dow === 0 || dow === 6);
        c.setHours(wkend ? 10 : 8, wkend ? 0 : 30, 0, 0);
        if (c > now) return Math.floor(c.getTime()/1000);
    }
    return null;
}
const run = nextSlot(() => true);
const mop = nextSlot(d => d === 1 || d === 5);
const out = [];
if (run) out.push({payload:{ent:'input_datetime.rr_next_run', ts:run}});
if (mop) out.push({payload:{ent:'input_datetime.rr_next_mop', ts:mop}});
return [out];

// Phase-level run tracker. Publishes sensor.rr_run_progress via HA REST (out 0)
// and emits guarded room stamps (out 1, same shape s_room consumes).
const REST_ROOMS = ['master_bedroom_closet','master_bathroom','bathroom_1',
    'bedroom_1','kitchen','living_room','front_door_entry','garage_entrance',
    'half_bath','laundry_room','hallway','rachels_office'];
let run = flow.get('rr_run') || {active:false, phase:'', cancelled:false, near:''};
const evt = msg.rr_evt;
let stamp = null;
switch (evt) {
    case 'start':
        run = {active:true, phase:'Master bedroom — zone A', cancelled:false, near:''};
        break;
    case 'zoneB':
        run.phase = 'Master bedroom — zone B'; break;
    case 'zbdone':
        if (run.active && !run.cancelled && !flow.get('rr_cancel') && !flow.get('rr_mbr_short')) {
            stamp = {stamp:'input_datetime.rr_last_clean_master_bedroom',
                     ts: Math.floor(Date.now()/1000)};
            run.phase = 'Dock — emptying before main sweep';
        }
        break;
    case 'rest':
        run.phase = 'Main floor sweep (12 rooms)'; break;
    case 'restdone':
        if (run.active && !run.cancelled && !flow.get('rr_cancel')) {
            stamp = {stamp: REST_ROOMS.map(r => 'input_datetime.rr_last_clean_' + r),
                     ts: Math.floor(Date.now()/1000)};
            run.phase = 'Main sweep complete';
        }
        break;
    case 'mop':
        run.phase = 'Mop pass (all floors)'; break;
    case 'done':
        run.phase = run.cancelled ? 'Cancelled' : 'Complete';
        run.active = false; run.near = '';
        break;
    case 'cancel':
        run.cancelled = true; run.active = false;
        run.phase = 'Cancelled — returning to dock';
        break;
    case 'failed':
        run.cancelled = true; run.active = false; run.near = '';
        run.phase = msg.rr_phase || 'Failed';
        break;
    case 'idle':
        if (run.active && !run.cancelled) {
            run.cancelled = true; run.active = false;
            flow.set('rr_cancel', true);
            run.phase = 'Stopped by hand — rest of run cancelled';
        } else { return null; }
        break;
    case 'room':
        if (!run.active) return null;
        run.near = String(msg.payload || '');
        break;
    default:
        return null;
}
flow.set('rr_run', run);
const prog = {payload: {phase: run.phase.substring(0,255), near: (run.near || '').substring(0,100)}};
return [[prog], stamp ? [{payload: stamp}] : []];

const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);

const probs = [];
if (st('binary_sensor.mr_slave_water_shortage_2') === 'on') probs.push('clean-water tank is empty');
const dock = st('sensor.mr_slave_dock_dock_error');
if (dock && !['ok','unknown','unavailable'].includes(dock)) probs.push('dock reports ' + dock.replace(/_/g,' '));
const verr = st('vacuum.mr_slave_2') === 'error' ? st('sensor.mr_slave_vacuum_error_2') : null;
if (verr && verr !== 'none') probs.push('robot error ' + verr.replace(/_/g,' '));
flow.set('rr_mop_skip', probs.length > 0);
flow.set('rr_mbr_short', false);
flow.set('rr_zone_t', Date.now());
if (!Object.keys(_st).length) node.warn('preflight: HA state store empty, skipping checks');
const d = new Date().getDay();
const mopDay = (d === 1 || d === 5);
let note = null;
if (probs.length) {
    note = {notify: {title: 'Vacuum: check the dock',
        message: 'Starting the daily clean, but the ' + probs.join(' and ') + '. ' +
                 (mopDay ? 'Vacuum pass only — today\'s mop pass will be skipped.' : 'Vacuum pass only.'),
        tag: 'rr_preflight', urgent: false}};
}
node.status(probs.length ? {fill:'yellow',text:probs.join(', ')} : {fill:'green',text:'ok'});
return [msg, note];

const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);

flow.set('rr_zone_t', Date.now());
const m = st('select.mr_slave_cleaning_mode');
if (m === 'vacuum' || m === undefined) { node.status({fill:'green',text:String(m)}); return [msg, null]; }
node.warn('cleaning mode is ' + m + ' after set; retrying once (A)');
node.status({fill:'yellow',text:'retry: was ' + m});
return [null, msg];

