return [null, msg];

const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);

flow.set('rr_cancel', true);
const status = st('sensor.mr_slave_status_2') || 'unknown';
const notify = {notify: {title: 'Vacuum: daily clean stopped', message: msg.rr_stage + ' did not finish within ' + msg.rr_mins + ' min.' + ' Vacuum is ' +
    status.replace(/_/g,' ') + '. The rest of today\'s run is cancelled.', tag: 'rr_run_failed', urgent: true}};
const evt = {rr_evt: 'failed', rr_phase: 'Stalled — ' + msg.rr_stage};
node.status({fill:'red', text: 'Stalled — ' + msg.rr_stage});
return [notify, evt, {payload: 'restore'}];

const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);

flow.set('rr_cancel', true);
const status = st('sensor.mr_slave_status_2') || 'unknown';
const notify = {notify: {title: 'Vacuum: daily clean stopped', message: 'Step "' + ((msg.error && msg.error.source && msg.error.source.name) || '?') + '" failed: ' + ((msg.error && msg.error.message) || 'unknown error') + '.' + ' Vacuum is ' +
    status.replace(/_/g,' ') + '. The rest of today\'s run is cancelled.', tag: 'rr_run_failed', urgent: true}};
const evt = {rr_evt: 'failed', rr_phase: 'Failed — ' + ((msg.error && msg.error.source && msg.error.source.name) || 'command error')};
node.status({fill:'red', text: 'Failed — ' + ((msg.error && msg.error.source && msg.error.source.name) || 'command error')});
return [notify, evt, {payload: 'restore'}];

const mins = (Date.now() - (flow.get('rr_zone_t') || Date.now())) / 60000;
node.status({fill: mins < 5 ? 'yellow' : 'green', text: mins.toFixed(1) + ' min'});
if (mins >= 5) return [msg, null];
flow.set('rr_mbr_short', true);
return [msg, {notify: {title: 'Vacuum: bedroom zone A ended early',
    message: 'Master bedroom zone A was back at the dock after ' + mins.toFixed(1) +
             ' min (normally ~20). The run continues; the bedroom is not marked cleaned.',
    tag: 'rr_short_zone', urgent: false}}];

